styles:
 /*Price styling*/

.bg-white {
  background: #000000!important;
}

.price-desc li {
    list-style: none!important;
    padding: 0 8px!important;
    border-right: 1px solid #d4d4d4!important;
    display: inline-block!important;
}
.price-list {
  text-align: center!important;
    padding: 30px 30px 0!important;
    -webkit-border-radius: 8px!important;
    border-radius: 8px!important;
    box-shadow: 0 3.4px 2.7px -30px rgb(0 0 0 / 6%), 0 8.2px 8.9px -30px rgb(0 0 0 / 7%), 0 25px 40px -30px rgb(0 0 0 / 20%)!important;
    margin: 30px!important;
    /*padding: 30px;*/
    background: #cac9c921;
}
.color-box {
  width: 9px!important;
    height: 9px!important;
    font-size: 16px!important;
    border-radius: 50%!important;
    display: inline-block!important;
    margin-right: 8px!important;
    border: 1px solid #22222269!important;
    padding: 2px!important;
 }
.pine-gray {
  background-color: #4b555c!important;
}
.lilac-mist{
  background-color: #d7d2dc!important;
}
.jade-black{
  background-color: #1e1e23!important;
}
.celetial-blue{
    background-color: #3d4b4c!important;
}
.indie-black {
  background-color: #000000!important;
}
.gaia-green {
  background-color: #0caaaa!important;
}
.price-desc {
    margin-top: 10px!important;
}
.price-main-btn {
  font-size: 16px!important;
    font-weight: 400!important;
    font-family: Poppins,sans-serif!important;
    padding: 0 26px!important;
    line-height: 44px!important;
    outline: 0!important;
    color: #fff!important;
    background-color: #ff1f8e!important;
    border: none!important;
    -webkit-border-radius: 100px!important;
    border-radius: 100px!important;
    display: inline-block!important;
    position: relative!important;
    -webkit-box-shadow: 0 10px 15px 0 rgb(233 30 99 / 15%)!important;
    box-shadow: 0 10px 15px 0 rgb(233 30 99 / 15%)!important;
}
.price-buy {
    margin-top: 26px!important;
    margin-bottom: -27px!important;
    display: inline-block!important;
}
.price-btn {
    background: #673AB7!important;
    background: -moz-linear-gradient(left,#673AB7 0,#2196F3 100%)!important;
    background: -webkit-linear-gradient(left,#673AB7 0,#2196F3 100%)!important;
    background: linear-gradient(to right,#673AB7 0,#2196F3 100%)!important;
    box-shadow: 0 10px 15px 0 rgb(56 0 189 / 20%)!important;
}
.price-head h3 {
	font-size: 21px!important;
    color: #00a3e7!important;
}
.price-head h4 {
    font-size: 146.5%!important;
    line-height: 2!important;
}
.price-main-btn:hover {
    background: -webkit-linear-gradient(left,#2196F3 0,#673AB7 100%)!important;
    background: linear-gradient(to right,#2196F3 0,#673AB7 100%)!important;
}
.price-desc li:last-child {
    border-right: none!important;
}
.col-centered{
    display:inline-block!important;
    float:none!important;
	width: 40%!important;
}
@media screen and (max-width: 730px){
.col-centered{
	width: 100%!important;
}
}
.section_price {
    background-color: #000000;
    padding-bottom: 60px!important;
}  /*缩短上下间距改成60 之前120*; 改背景色从#f9f9f9;为#000000;*/
.section_video {
    background-color: #000000;
    padding-bottom: 60px!important;
} /*缩短上下间距改成60 之前120; 改背景色从#f9f9f9;为#000000;*/
.video-inner {
    margin: 10px!important;
}
.video_title {
    margin-bottom: 18px!important;
    font-size: 48px!important;
    color: #000!important;
}


.btn-wtb a {
    background-color: #27a8c8;
    padding: 5px 40px;
    display: inline-block;
    font-size: 20px;
    border-radius: 30px;
    font-family: "Prompt", sans-serif !important;
    color: #fff;
}  

 .fadeIn {
    -webkit-animation-name: fadeIn;
    animation-name: fadeIn;
}

.start-wow {
    visibility: hidden;
}



    .wow.animated {
    -webkit-animation-duration: 1.5s;
    -moz-animation-duration: 1.5s;
    -ms-animation-duration: 1.5s;
    -o-animation-duration: 1.5s;
    animation-duration: 1.5s
}


    @media (max-width:480px) {


    .btn-wtb a {
        font-size: 14px;
    } 



    }


    @media all and (min-width: 1920px) {
        #ASUS-features .section__kv .video__wrap video {
            min-height: 1020px;
        }
        #ASUS-features .section__1 .video__wrap video {
            min-height: 1020px;
        }
        #ASUS-features .section__2 .video__wrap video {
            min-height: 1020px;
        }
        #ASUS-features .section__5 .video__full__wrap video {
            min-height: 1020px;
        }

    }
    @media all and (min-width: 737px) and (max-width: 1800px) {
        #ASUS-features .section__kv .video__wrap video {
            min-height: 750px;
        }
        #ASUS-features .section__1 .video__wrap video {
            min-height: 750px;
        }
        #ASUS-features .section__2 .video__wrap video {
            min-height: 750px;
        }
        #ASUS-features .section__5 .video__full__wrap video {
            min-height: 750px;
        }
    }
